{"step": 1, "unit": "scripts/move-to-emeritus.py::create_emeritus_prs", "suspicions": [{"label": "a", "lines": [1198, 1199, 1200, 1201, 1202, 1203, 1204, 1205, 1206, 1207, 1208, 1209, 1210], "why": "For each user and each of their roles, the same README sections are located with _find_section and re-parsed with _parse_members to find a display name, so every README section is parsed once per user rather than once per repo."}, {"label": "b", "lines": [1223, 1224, 1225, 1230], "why": "The README string is rebuilt in full by each _remove_member_line and _add_to_emeritus call, so each user costs several full copies of the README."}]}
{"step": 1, "unit": "scripts/move-to-emeritus.py::_ensure_fork", "suspicions": [{"label": "a", "lines": [967, 968], "why": "After the fork POST the loop sleeps 5 s before its first check of the fork, so a fork that is already ready still costs at least 5 s of wall-clock idle time."}, {"label": "b", "lines": [982, 983, 984, 985, 989], "why": "The refs endpoint is polled with a fixed 5 s sleep between attempts rather than a shorter backoff, so each wait is at least 5 s."}]}
